  else if (act === 'пьёт') { View.people.act(c.pid, 'sip', done); if (dec.stars >= 5) logEvent(`${c.name} ${vf(c, 'отпил и расплылся', 'отпила и расплылась')} в улыбке`, 'happy', true); }
  else done();
