function run(puzzle, solution, limit) {
  const S = create(puzzle, solution);
  while (!S.won && !S.error && S.t < (limit || 2000)) step(S);
  return { won: S.won, error: S.error, cycles: S.t, cost: S.cost, area: S.area.size, produced: S.produced };
}

